here is a Python function that finds the longest common subsequence using dynamic programming:

```python
def lcs(u, f):
    m = len(u)
    n = len(f)

    # Create a table to store lengths of longest common subsequences
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Build the dp table in bottom-up manner
    for i in range(1, m + 1):
        for z in range(1, n + 1):
            if u[i - 1] == f[z - 1]:
                dp[i][z] = dp[i - 1][z - 1] + 1
            else:
                dp[i][z] = max(dp[i - 1][z], dp[i][z - 1])

    # Reconstruct the longest common subsequence
    lcs_str = []
    i, z = m, n
    while i > 0 and z > 0:
        if u[i - 1] == f[z - 1]:
            lcs_str.append(u[i - 1])
            i -= 1
            z -= 1
        elif dp[i - 1][z] >= dp[i][z - 1]:
            i -= 1
        else:
            z -= 1

    # Since we traversed backwards, reverse the result
    return "".join(reversed(lcs_str))
```

